&reftitle.returnvalues;


 PDO::getAvailableDrivers restituisce un array di nomi di driver PDO.
 Se non è disponibile alcun driver, restituisce un array vuoto.

  &reftitle.examples;



    Esempio di PDO::getAvailableDrivers


<?php
print_r(PDO::getAvailableDrivers());
?>


    &example.outputs.similar;


Array
(
    [0] => mysql
    [1] => sqlite
)
